// A runtime variable
int sz = 10;

// const can be initialized at runtime
const auto arraySizeConst = sz; // OK

// constexpr MUST be initialized at compile-time
constexpr auto arraySizeExpr = 10; // OK

// Use in a compile-time context
std::array<int, arraySizeExpr> data1; // OK
// std::array<int, arraySizeConst> data2; // ERROR! arraySizeConst is not a compile-time constant

// All constexpr are const
// arraySizeExpr = 20; // ERROR! read-only
